<?php require 'config/db.php';$products=$pdo->query("SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.status IN ('active','sold') ORDER BY FIELD(p.status,'active','sold'),p.featured DESC,p.name")->fetchAll();$page_title='Products';include 'includes/header.php';?><section class="page-hero product-page-hero"><div class="container"><span class="eyebrow">Mhofu Inventory</span><h1>Clear stock visibility for <span class="gradient-text">every product.</span></h1><p class="lead">Browse available, low-stock, out-of-stock and sold products in one clean catalogue.</p></div></section><section class="content-shell"><div class="container"><div class="catalog-toolbar"><div><b><?=count($products)?> catalogue items</b><span>Live stock status from the inventory system</span></div><div class="catalog-legend"><span class="status in">Available</span><span class="status low">Low stock</span><span class="status out">Sold / Out</span></div></div><div class="product-public-grid"><?php foreach($products as $p):$sold=$p['status']==='sold';$state=$sold?'Sold':($p['quantity']<=0?'Out of Stock':($p['quantity']<=$p['minimum_stock']?'Low Stock':'Available'));$cls=($sold||$p['quantity']<=0)?'out':($p['quantity']<=$p['minimum_stock']?'low':'in');?><article class="public-product-card <?=$sold?'is-sold':''?>"><div class="public-product-image"><img src="<?=e($p['image_url']?:'assets/img/site/hero-1.jpg')?>" alt="<?=e($p['name'])?>"><span class="status <?=$cls?>"><?=$state?></span></div><div class="public-product-body"><span class="product-meta"><?=e($p['category']??'Uncategorised')?> · <?=e($p['sku'])?></span><h3><?=e($p['name'])?></h3><p><?=e($p['description'])?></p><div class="public-product-bottom"><div><small>Selling price</small><strong>$<?=number_format($p['selling_price'],2)?></strong></div><div class="stock-number"><small>Stock</small><strong><?=$p['quantity']?> <?=e($p['unit'])?></strong></div></div></div></article><?php endforeach;?></div></div></section><?php include 'includes/footer.php'; ?>